import React, { useState, useEffect, useRef } from 'react';
import { useAuth } from '../contexts/AuthContext';
import PageLayout from '../components/PageLayout';
import LoadingSpinner from '../components/LoadingSpinner';

const Camera = () => {
  const { user } = useAuth();
  const [cameraStatus, setCameraStatus] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);
  const [streamUrl, setStreamUrl] = useState(null);
  const videoRef = useRef(null);

  // Get camera status
  const getCameraStatus = async () => {
    try {
      const token = localStorage.getItem('token');
      const response = await fetch('/api/control/camera/status', {
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        }
      });

      const data = await response.json();
      
      if (response.ok) {
        setCameraStatus(data);
        if (data.cameraStatus?.camera_active) {
          setStreamUrl(`http://localhost:5001/camera/stream`);
        } else {
          setStreamUrl(null);
        }
      } else {
        setError(data.error || 'Failed to get camera status');
      }
    } catch (err) {
      setError('Network error: ' + err.message);
    }
  };

  // Start camera
  const startCamera = async () => {
    setIsLoading(true);
    setError(null);

    try {
      const token = localStorage.getItem('token');
      const response = await fetch('/api/control/camera/start', {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        }
      });

      const data = await response.json();
      
      if (response.ok) {
        setStreamUrl(`http://localhost:5001/camera/stream`);
        await getCameraStatus(); // Refresh status
      } else {
        setError(data.error || 'Failed to start camera');
      }
    } catch (err) {
      setError('Network error: ' + err.message);
    } finally {
      setIsLoading(false);
    }
  };

  // Stop camera
  const stopCamera = async () => {
    setIsLoading(true);
    setError(null);

    try {
      const token = localStorage.getItem('token');
      const response = await fetch('/api/control/camera/stop', {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        }
      });

      const data = await response.json();
      
      if (response.ok) {
        setStreamUrl(null);
        await getCameraStatus(); // Refresh status
      } else {
        setError(data.error || 'Failed to stop camera');
      }
    } catch (err) {
      setError('Network error: ' + err.message);
    } finally {
      setIsLoading(false);
    }
  };

  // Check status on component mount
  useEffect(() => {
    getCameraStatus();
    
    // Set up interval to check status every 5 seconds
    const interval = setInterval(getCameraStatus, 5000);
    
    return () => clearInterval(interval);
  }, []);

  // Handle video load error
  const handleVideoError = () => {
    setError('Failed to load camera stream');
    setStreamUrl(null);
  };

  if (!cameraStatus) {
    return (
      <PageLayout>
        <div className="flex justify-center items-center h-64">
          <LoadingSpinner />
        </div>
      </PageLayout>
    );
  }

  if (!cameraStatus.hasActiveBooking) {
    return (
      <PageLayout>
        <div className="max-w-4xl mx-auto p-6">
          <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-6 text-center">
            <div className="text-yellow-600 mb-4">
              <svg className="w-16 h-16 mx-auto" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" />
              </svg>
            </div>
            <h2 className="text-xl font-semibold text-yellow-800 mb-2">No Active Booking</h2>
            <p className="text-yellow-700">
              You need an active booking to access the camera. Please make a booking first.
            </p>
          </div>
        </div>
      </PageLayout>
    );
  }

  return (
    <PageLayout>
      <div className="max-w-6xl mx-auto p-6">
        <div className="mb-6">
          <h1 className="text-3xl font-bold text-gray-900 mb-2">Camera Control</h1>
          <p className="text-gray-600">
            Monitor your robot's field through the Raspberry Pi camera
          </p>
        </div>

        {/* Status Card */}
        <div className="bg-white rounded-lg shadow-md p-6 mb-6">
          <h2 className="text-xl font-semibold text-gray-900 mb-4">Camera Status</h2>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="text-center">
              <div className={`inline-flex items-center px-3 py-1 rounded-full text-sm font-medium ${
                cameraStatus.cameraStatus?.camera_active 
                  ? 'bg-green-100 text-green-800' 
                  : 'bg-gray-100 text-gray-800'
              }`}>
                <div className={`w-2 h-2 rounded-full mr-2 ${
                  cameraStatus.cameraStatus?.camera_active ? 'bg-green-400' : 'bg-gray-400'
                }`}></div>
                {cameraStatus.cameraStatus?.camera_active ? 'Active' : 'Inactive'}
              </div>
              <p className="text-sm text-gray-600 mt-1">Camera Status</p>
            </div>
            
            <div className="text-center">
              <div className="text-lg font-semibold text-gray-900">
                {cameraStatus.cameraStatus?.current_user || 'None'}
              </div>
              <p className="text-sm text-gray-600">Current User</p>
            </div>
            
            <div className="text-center">
              <div className="text-lg font-semibold text-gray-900">
                {cameraStatus.booking?.status || 'Unknown'}
              </div>
              <p className="text-sm text-gray-600">Booking Status</p>
            </div>
          </div>
        </div>

        {/* Control Buttons */}
        <div className="bg-white rounded-lg shadow-md p-6 mb-6">
          <h2 className="text-xl font-semibold text-gray-900 mb-4">Camera Controls</h2>
          <div className="flex flex-wrap gap-4">
            <button
              onClick={startCamera}
              disabled={isLoading || cameraStatus.cameraStatus?.camera_active}
              className={`px-6 py-3 rounded-lg font-medium transition-colors ${
                isLoading || cameraStatus.cameraStatus?.camera_active
                  ? 'bg-gray-300 text-gray-500 cursor-not-allowed'
                  : 'bg-green-600 text-white hover:bg-green-700'
              }`}
            >
              {isLoading ? 'Starting...' : 'Start Camera'}
            </button>
            
            <button
              onClick={stopCamera}
              disabled={isLoading || !cameraStatus.cameraStatus?.camera_active}
              className={`px-6 py-3 rounded-lg font-medium transition-colors ${
                isLoading || !cameraStatus.cameraStatus?.camera_active
                  ? 'bg-gray-300 text-gray-500 cursor-not-allowed'
                  : 'bg-red-600 text-white hover:bg-red-700'
              }`}
            >
              {isLoading ? 'Stopping...' : 'Stop Camera'}
            </button>
            
            <button
              onClick={getCameraStatus}
              disabled={isLoading}
              className={`px-6 py-3 rounded-lg font-medium transition-colors ${
                isLoading
                  ? 'bg-gray-300 text-gray-500 cursor-not-allowed'
                  : 'bg-blue-600 text-white hover:bg-blue-700'
              }`}
            >
              {isLoading ? 'Refreshing...' : 'Refresh Status'}
            </button>
          </div>
        </div>

        {/* Error Display */}
        {error && (
          <div className="bg-red-50 border border-red-200 rounded-lg p-4 mb-6">
            <div className="flex">
              <div className="text-red-400 mr-3">
                <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20">
                  <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
                </svg>
              </div>
              <div>
                <h3 className="text-sm font-medium text-red-800">Error</h3>
                <p className="text-sm text-red-700 mt-1">{error}</p>
              </div>
            </div>
          </div>
        )}

        {/* Camera Stream */}
        <div className="bg-white rounded-lg shadow-md p-6">
          <h2 className="text-xl font-semibold text-gray-900 mb-4">Live Camera Feed</h2>
          
          {streamUrl ? (
            <div className="relative">
              <video
                ref={videoRef}
                src={streamUrl}
                autoPlay
                muted
                playsInline
                className="w-full max-w-4xl mx-auto rounded-lg shadow-lg"
                onError={handleVideoError}
                style={{ maxHeight: '480px' }}
              />
              <div className="absolute top-4 right-4 bg-black bg-opacity-50 text-white px-3 py-1 rounded-full text-sm">
                LIVE
              </div>
            </div>
          ) : (
            <div className="bg-gray-100 rounded-lg p-12 text-center">
              <div className="text-gray-400 mb-4">
                <svg className="w-16 h-16 mx-auto" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" />
                </svg>
              </div>
              <h3 className="text-lg font-medium text-gray-900 mb-2">Camera Not Active</h3>
              <p className="text-gray-600">
                Click "Start Camera" to begin live streaming from the Raspberry Pi camera.
              </p>
            </div>
          )}
        </div>
      </div>
    </PageLayout>
  );
};

export default Camera;
